#include <stddef.h>
#include <math.h>
#include <arm_neon.h>

static inline float32x4_t a_load4(const float *p, size_t s) {
    if (s == 1) return vld1q_f32(p);
    float32x4_t v = vdupq_n_f32(p[0]);
    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2*s], v, 2);
    return vsetq_lane_f32(p[3*s], v, 3);
}

static inline float a_maximum(const float *p, size_t n, size_t s) {
    float32x4_t m0 = vdupq_n_f32(-INFINITY);
    float32x4_t m1 = m0, m2 = m0, m3 = m0;
    size_t j = 0;
    for (; n-j >= 16; j += 16) {
        m0 = vmaxq_f32(m0, a_load4(p+j*s, s));
        m1 = vmaxq_f32(m1, a_load4(p+(j+4)*s, s));
        m2 = vmaxq_f32(m2, a_load4(p+(j+8)*s, s));
        m3 = vmaxq_f32(m3, a_load4(p+(j+12)*s, s));
    }
    float32x4_t m = vmaxq_f32(vmaxq_f32(m0, m1), vmaxq_f32(m2, m3));
    for (; n-j >= 4; j += 4)
        m = vmaxq_f32(m, a_load4(p+j*s, s));
    float maximum = vmaxvq_f32(m);
    for (; j < n; ++j) {
        float v = p[j*s];
        if (v > maximum) maximum = v;
    }
    return maximum;
}

static inline float a_exponential(float d) {
    return d == 0.0f ? 1.0f : expf(d);
}

static inline void a_scale(float *p, size_t n, float scale) {
    float32x4_t v = vdupq_n_f32(scale);
    size_t j = 0;
    for (; n-j >= 16; j += 16) {
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
        vst1q_f32(p+j+4, vmulq_f32(vld1q_f32(p+j+4), v));
        vst1q_f32(p+j+8, vmulq_f32(vld1q_f32(p+j+8), v));
        vst1q_f32(p+j+12, vmulq_f32(vld1q_f32(p+j+12), v));
    }
    for (; n-j >= 4; j += 4)
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
    for (; j < n; ++j) p[j] *= scale;
}

static inline void a_row(const float *restrict p, float *restrict y,
                         size_t n, size_t s) {
    float maximum = a_maximum(p, n, s);
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n-j >= 4; j += 4) {
        float e = a_exponential(p[j*s]-maximum);
        y[j] = e; s0 += (double)e;
        e = a_exponential(p[(j+1)*s]-maximum);
        y[j+1] = e; s1 += (double)e;
        e = a_exponential(p[(j+2)*s]-maximum);
        y[j+2] = e; s2 += (double)e;
        e = a_exponential(p[(j+3)*s]-maximum);
        y[j+3] = e; s3 += (double)e;
    }
    for (; j < n; ++j) {
        float e = a_exponential(p[j*s]-maximum);
        y[j] = e; s0 += (double)e;
    }
    double sum = (s0+s1)+(s2+s3);
    a_scale(y, n, (float)(1.0/sum));
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)inv; (void)px; (void)pr;
    if (rows == 0 || cols == 0) return;
    if (cols == 1) {
        for (size_t i = 0; i < rows; ++i) out[i] = 1.0f;
        return;
    }
    if (cs == 1) {
        for (size_t i = 0; i < rows; ++i)
            a_row(x+i*rs, out+i*cols, cols, 1);
    } else {
        for (size_t i = 0; i < rows; ++i)
            a_row(x+i*rs, out+i*cols, cols, cs);
    }
}

#include <stddef.h>
#include <math.h>
#include <arm_neon.h>

static inline float32x4_t b_load4(const float *p, size_t s) {
    if (s == 1) return vld1q_f32(p);
    float32x4_t v = vdupq_n_f32(p[0]);
    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2*s], v, 2);
    return vsetq_lane_f32(p[3*s], v, 3);
}

static inline float b_maximum(const float *p, size_t n) {
    float32x4_t m0 = vdupq_n_f32(-INFINITY), m1 = m0;
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        m0 = vmaxq_f32(m0, vld1q_f32(p+j));
        m1 = vmaxq_f32(m1, vld1q_f32(p+j+4));
    }
    float32x4_t m = vmaxq_f32(m0, m1);
    for (; n-j >= 4; j += 4) m = vmaxq_f32(m, vld1q_f32(p+j));
    float maximum = vmaxvq_f32(m);
    for (; j < n; ++j) if (p[j] > maximum) maximum = p[j];
    return maximum;
}

static inline float b_pack_row(const float *restrict p, float *restrict d,
                               size_t n, size_t s) {
    float32x4_t m0 = vdupq_n_f32(-INFINITY), m1 = m0;
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        float32x4_t v0 = b_load4(p+j*s, s);
        float32x4_t v1 = b_load4(p+(j+4)*s, s);
        vst1q_f32(d+j, v0);
        vst1q_f32(d+j+4, v1);
        m0 = vmaxq_f32(m0, v0);
        m1 = vmaxq_f32(m1, v1);
    }
    float32x4_t m = vmaxq_f32(m0, m1);
    for (; n-j >= 4; j += 4) {
        float32x4_t v = b_load4(p+j*s, s);
        vst1q_f32(d+j, v);
        m = vmaxq_f32(m, v);
    }
    float maximum = vmaxvq_f32(m);
    for (; j < n; ++j) {
        float v = p[j*s];
        d[j] = v;
        if (v > maximum) maximum = v;
    }
    return maximum;
}

static inline float b_exponential(float d) {
    return d == 0.0f ? 1.0f : expf(d);
}

static inline void b_finish(const float *restrict p, float *restrict y,
                            size_t n, float maximum) {
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n-j >= 4; j += 4) {
        float e = b_exponential(p[j]-maximum);
        y[j] = e; s0 += (double)e;
        e = b_exponential(p[j+1]-maximum);
        y[j+1] = e; s1 += (double)e;
        e = b_exponential(p[j+2]-maximum);
        y[j+2] = e; s2 += (double)e;
        e = b_exponential(p[j+3]-maximum);
        y[j+3] = e; s3 += (double)e;
    }
    for (; j < n; ++j) {
        float e = b_exponential(p[j]-maximum);
        y[j] = e; s0 += (double)e;
    }
    float scale = (float)(1.0/((s0+s1)+(s2+s3)));
    float32x4_t v = vdupq_n_f32(scale);
    j = 0;
    for (; n-j >= 8; j += 8) {
        vst1q_f32(y+j, vmulq_f32(vld1q_f32(y+j), v));
        vst1q_f32(y+j+4, vmulq_f32(vld1q_f32(y+j+4), v));
    }
    for (; n-j >= 4; j += 4)
        vst1q_f32(y+j, vmulq_f32(vld1q_f32(y+j), v));
    for (; j < n; ++j) y[j] *= scale;
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)inv; (void)pr;
    if (rows == 0 || cols == 0) return;
    if (cols == 1) {
        for (size_t i = 0; i < rows; ++i) out[i] = 1.0f;
        return;
    }
    if (cs == 1) {
        for (size_t i = 0; i < rows; ++i) {
            const float *p = x+i*rs;
            float maximum = b_maximum(p, cols);
            b_finish(p, out+i*cols, cols, maximum);
        }
        return;
    }
    size_t start = 0;
    if (rs < cs) {
        for (; rows-start >= 4; start += 4) {
            const float *p = x+start*rs;
            float *d0 = px+start*cols;
            float *d1 = d0+cols;
            float *d2 = d1+cols;
            float *d3 = d2+cols;
            float32x4_t m0 = vdupq_n_f32(-INFINITY);
            float32x4_t m1 = m0, m2 = m0, m3 = m0;
            size_t j = 0;
            for (; cols-j >= 4; j += 4) {
                float32x4_t c0 = b_load4(p+j*cs, rs);
                float32x4_t c1 = b_load4(p+(j+1)*cs, rs);
                float32x4_t c2 = b_load4(p+(j+2)*cs, rs);
                float32x4_t c3 = b_load4(p+(j+3)*cs, rs);
                m0 = vmaxq_f32(m0, c0);
                m1 = vmaxq_f32(m1, c1);
                m2 = vmaxq_f32(m2, c2);
                m3 = vmaxq_f32(m3, c3);
                float32x4_t t0 = vtrn1q_f32(c0, c1);
                float32x4_t t1 = vtrn2q_f32(c0, c1);
                float32x4_t t2 = vtrn1q_f32(c2, c3);
                float32x4_t t3 = vtrn2q_f32(c2, c3);
                vst1q_f32(d0+j, vcombine_f32(vget_low_f32(t0), vget_low_f32(t2)));
                vst1q_f32(d1+j, vcombine_f32(vget_low_f32(t1), vget_low_f32(t3)));
                vst1q_f32(d2+j, vcombine_f32(vget_high_f32(t0), vget_high_f32(t2)));
                vst1q_f32(d3+j, vcombine_f32(vget_high_f32(t1), vget_high_f32(t3)));
            }
            float32x4_t m = vmaxq_f32(vmaxq_f32(m0, m1), vmaxq_f32(m2, m3));
            for (; j < cols; ++j) {
                float32x4_t v = b_load4(p+j*cs, rs);
                m = vmaxq_f32(m, v);
                d0[j] = vgetq_lane_f32(v, 0);
                d1[j] = vgetq_lane_f32(v, 1);
                d2[j] = vgetq_lane_f32(v, 2);
                d3[j] = vgetq_lane_f32(v, 3);
            }
            float maxima[4];
            vst1q_f32(maxima, m);
            b_finish(d0, out+start*cols, cols, maxima[0]);
            b_finish(d1, out+(start+1)*cols, cols, maxima[1]);
            b_finish(d2, out+(start+2)*cols, cols, maxima[2]);
            b_finish(d3, out+(start+3)*cols, cols, maxima[3]);
        }
    }
    for (; start < rows; ++start) {
        float *d = px+start*cols;
        float maximum = b_pack_row(x+start*rs, d, cols, cs);
        b_finish(d, out+start*cols, cols, maximum);
    }
}

#include <stddef.h>
#include <stdint.h>
#include <math.h>
#include <arm_neon.h>

typedef struct { float lo, hi; } c_range;

static inline float32x4_t c_load4(const float *p, size_t s) {
    if (s == 1) return vld1q_f32(p);
    float32x4_t v = vdupq_n_f32(p[0]);
    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2*s], v, 2);
    return vsetq_lane_f32(p[3*s], v, 3);
}

static inline c_range c_bounds(const float *p, size_t n, size_t s) {
    float32x4_t h0 = vdupq_n_f32(-INFINITY), h1 = h0;
    float32x4_t l0 = vdupq_n_f32(INFINITY), l1 = l0;
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        float32x4_t a = c_load4(p+j*s, s);
        float32x4_t b = c_load4(p+(j+4)*s, s);
        h0 = vmaxq_f32(h0, a);
        h1 = vmaxq_f32(h1, b);
        l0 = vminq_f32(l0, a);
        l1 = vminq_f32(l1, b);
    }
    float32x4_t h = vmaxq_f32(h0, h1);
    float32x4_t l = vminq_f32(l0, l1);
    for (; n-j >= 4; j += 4) {
        float32x4_t v = c_load4(p+j*s, s);
        h = vmaxq_f32(h, v);
        l = vminq_f32(l, v);
    }
    c_range result = { vminvq_f32(l), vmaxvq_f32(h) };
    for (; j < n; ++j) {
        float v = p[j*s];
        if (v < result.lo) result.lo = v;
        if (v > result.hi) result.hi = v;
    }
    return result;
}

static inline void c_fill(float *p, size_t n, float value) {
    float32x4_t v = vdupq_n_f32(value);
    size_t j = 0;
    for (; n-j >= 4; j += 4) vst1q_f32(p+j, v);
    for (; j < n; ++j) p[j] = value;
}

static inline void c_scale(float *p, size_t n, float scale) {
    float32x4_t v = vdupq_n_f32(scale);
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
        vst1q_f32(p+j+4, vmulq_f32(vld1q_f32(p+j+4), v));
    }
    for (; n-j >= 4; j += 4)
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
    for (; j < n; ++j) p[j] *= scale;
}

static inline void c_row(const float *restrict p, float *restrict y,
                         size_t n, size_t s) {
    c_range range = c_bounds(p, n, s);
    if (range.lo == range.hi) {
        c_fill(y, n, (float)(1.0/(double)n));
        return;
    }
    float32x4_t high = vdupq_n_f32(range.hi);
    float32x4_t low = vdupq_n_f32(range.lo);
    size_t high_count = 0;
    size_t j = 0;
    int binary = 1;
    for (; n-j >= 4; j += 4) {
        float32x4_t v = c_load4(p+j*s, s);
        uint32x4_t eh = vceqq_f32(v, high);
        uint32x4_t el = vceqq_f32(v, low);
        if (vminvq_u32(vorrq_u32(eh, el)) != UINT32_MAX) {
            binary = 0;
            break;
        }
        high_count += (size_t)vaddvq_u32(vshrq_n_u32(eh, 31));
    }
    if (binary) {
        for (; j < n; ++j) {
            float v = p[j*s];
            if (v == range.hi) ++high_count;
            else if (v != range.lo) {
                binary = 0;
                break;
            }
        }
    }
    if (binary) {
        float e = expf(range.lo-range.hi);
        double sum = (double)high_count + (double)(n-high_count)*(double)e;
        float ph = (float)(1.0/sum);
        float pl = e*ph;
        float32x4_t vh = vdupq_n_f32(ph);
        float32x4_t vl = vdupq_n_f32(pl);
        j = 0;
        for (; n-j >= 4; j += 4) {
            uint32x4_t mask = vceqq_f32(c_load4(p+j*s, s), high);
            vst1q_f32(y+j, vbslq_f32(mask, vh, vl));
        }
        for (; j < n; ++j) y[j] = p[j*s] == range.hi ? ph : pl;
        return;
    }
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    j = 0;
    for (; n-j >= 4; j += 4) {
        float e = expf(p[j*s]-range.hi);
        y[j] = e; s0 += (double)e;
        e = expf(p[(j+1)*s]-range.hi);
        y[j+1] = e; s1 += (double)e;
        e = expf(p[(j+2)*s]-range.hi);
        y[j+2] = e; s2 += (double)e;
        e = expf(p[(j+3)*s]-range.hi);
        y[j+3] = e; s3 += (double)e;
    }
    for (; j < n; ++j) {
        float e = expf(p[j*s]-range.hi);
        y[j] = e; s0 += (double)e;
    }
    c_scale(y, n, (float)(1.0/((s0+s1)+(s2+s3))));
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)inv; (void)px; (void)pr;
    if (rows == 0 || cols == 0) return;
    if (cols == 1) {
        for (size_t i = 0; i < rows; ++i) out[i] = 1.0f;
        return;
    }
    if (cs == 1) {
        for (size_t i = 0; i < rows; ++i)
            c_row(x+i*rs, out+i*cols, cols, 1);
    } else {
        for (size_t i = 0; i < rows; ++i)
            c_row(x+i*rs, out+i*cols, cols, cs);
    }
}

