    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2*s], v, 2);
    return vsetq_lane_f32(p[3*s], v, 3);
}

static inline void extrema(const float *p, size_t n, size_t s,
                           float *minimum, float *maximum) {
    if (n < 8) {
        float lo = p[0], hi = lo;
        for (size_t j = 1; j < n; ++j) {
            float a = p[j*s];
            if (a < lo) lo = a;
            if (a > hi) hi = a;
        }
        *minimum = lo;
        *maximum = hi;
        return;
    }
    float32x4_t h0 = vdupq_n_f32(-INFINITY), h1 = h0;
    float32x4_t l0 = vdupq_n_f32(INFINITY), l1 = l0;
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        float32x4_t a = read4(p+j*s, s);
        float32x4_t b = read4(p+(j+4)*s, s);
        h0 = vmaxq_f32(h0, a);
        h1 = vmaxq_f32(h1, b);
        l0 = vminq_f32(l0, a);
        l1 = vminq_f32(l1, b);
    }
    h0 = vmaxq_f32(h0, h1);
    l0 = vminq_f32(l0, l1);
    if (n-j >= 4) {
        float32x4_t a = read4(p+j*s, s);
        h0 = vmaxq_f32(h0, a);
        l0 = vminq_f32(l0, a);
        j += 4;
    }
    float hi = vmaxvq_f32(h0), lo = vminvq_f32(l0);
    for (; j < n; ++j) {
        float a = p[j*s];
        if (a > hi) hi = a;
        if (a < lo) lo = a;
    }
    *minimum = lo;
    *maximum = hi;
}

static inline void fill_row(float *p, size_t n, float a) {
    float32x4_t v = vdupq_n_f32(a);
    size_t j = 0;
    for (; n-j >= 4; j += 4) vst1q_f32(p+j, v);
    for (; j < n; ++j) p[j] = a;
}

static inline void scale_row(float *p, size_t n, float a) {
    float32x4_t v = vdupq_n_f32(a);
    size_t j = 0;
    for (; n-j >= 4; j += 4)
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
    for (; j < n; ++j) p[j] *= a;
}

static inline void process_row(const float *p, float *o, size_t n, size_t s) {
    float lo, hi;
    extrema(p, n, s, &lo, &hi);
    if (lo == hi) {
        fill_row(o, n, (float)(1.0/(double)n));
        return;
    }
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n-j >= 4; j += 4) {
        float e0 = expf(p[j*s]-hi);
        o[j] = e0;
        s0 += (double)e0;
        float e1 = expf(p[(j+1)*s]-hi);
        o[j+1] = e1;
        s1 += (double)e1;
        float e2 = expf(p[(j+2)*s]-hi);
        o[j+2] = e2;
        s2 += (double)e2;
        float e3 = expf(p[(j+3)*s]-hi);
        o[j+3] = e3;
        s3 += (double)e3;
    }
    for (; j < n; ++j) {
        float e = expf(p[j*s]-hi);
        o[j] = e;
        s0 += (double)e;
    }
    float a = (float)(1.0/((s0+s1)+(s2+s3)));
    scale_row(o, n, a);
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)inv; (void)px; (void)pr;
    if (rows == 0 || cols == 0) return;
    if (cols == 1) {
        fill_row(out, rows, 1.0f);
        return;
    }
    for (size_t i = 0; i < rows; ++i)
        process_row(x+i*rs, out+i*cols, cols, cs);
}

