        o[j] = e0;
        s0 += (double)e0;
        float e1 = expf(p[(j+1)*s]-hi);
        o[j+1] = e1;
        s1 += (double)e1;
        float e2 = expf(p[(j+2)*s]-hi);
        o[j+2] = e2;
