static inline void process_four(const float *p, float *o,
                                size_t n, size_t rs, size_t cs) {
    float32x4_t h0 = vdupq_n_f32(-INFINITY), h1 = h0;
    float32x4_t l0 = vdupq_n_f32(INFINITY), l1 = l0;
    size_t j = 0;
    for (; n-j >= 2; j += 2) {
        float32x4_t a = read4(p+j*cs, rs);
        float32x4_t b = read4(p+(j+1)*cs, rs);
        h0 = vmaxq_f32(h0, a);
        h1 = vmaxq_f32(h1, b);
        l0 = vminq_f32(l0, a);
        l1 = vminq_f32(l1, b);
    }
    h0 = vmaxq_f32(h0, h1);
    l0 = vminq_f32(l0, l1);
    if (j < n) {
        float32x4_t a = read4(p+j*cs, rs);
        h0 = vmaxq_f32(h0, a);
        l0 = vminq_f32(l0, a);
    }
    float hi[4], lo[4];
    vst1q_f32(hi, h0);
    vst1q_f32(lo, l0);
    float *o0 = o;
    float *o1 = o+n;
    float *o2 = o+2*n;
    float *o3 = o+3*n;
    if (hi[0] == lo[0] && hi[1] == lo[1] &&
        hi[2] == lo[2] && hi[3] == lo[3]) {
        float a = (float)(1.0/(double)n);
        fill_row(o0, n, a);
        fill_row(o1, n, a);
        fill_row(o2, n, a);
        fill_row(o3, n, a);
        return;
    }
    float m0 = hi[0], m1 = hi[1], m2 = hi[2], m3 = hi[3];
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    for (j = 0; j < n; ++j) {
        const float *a = p+j*cs;
        float e0 = expf(a[0]-m0);
        o0[j] = e0;
        s0 += (double)e0;
        float e1 = expf(a[rs]-m1);
        o1[j] = e1;
        s1 += (double)e1;
        float e2 = expf(a[2*rs]-m2);
        o2[j] = e2;
        s2 += (double)e2;
        float e3 = expf(a[3*rs]-m3);
        o3[j] = e3;
        s3 += (double)e3;
    }
    scale_row(o0, n, (float)(1.0/s0));
    scale_row(o1, n, (float)(1.0/s1));
    scale_row(o2, n, (float)(1.0/s2));
    scale_row(o3, n, (float)(1.0/s3));
}

