    float32x4_t h0 = vdupq_n_f32(-INFINITY), h1 = h0;
    float32x4_t l0 = vdupq_n_f32(INFINITY), l1 = l0;
    size_t j = 0;
    for (; n-j >= 8; j += 8) {
        float32x4_t a = read4(p+j*s, s);
        float32x4_t b = read4(p+(j+4)*s, s);
        h0 = vmaxq_f32(h0, a);
        h1 = vmaxq_f32(h1, b);
        l0 = vminq_f32(l0, a);
        l1 = vminq_f32(l1, b);
    }
    h0 = vmaxq_f32(h0, h1);
    l0 = vminq_f32(l0, l1);
    if (n-j >= 4) {
        float32x4_t a = read4(p+j*s, s);
        h0 = vmaxq_f32(h0, a);
        l0 = vminq_f32(l0, a);
        j += 4;
    }
    float hi = vmaxvq_f32(h0), lo = vminvq_f32(l0);
    for (; j < n; ++j) {
        float a = p[j*s];
        if (a > hi) hi = a;
        if (a < lo) lo = a;
    }
    *minimum = lo;
    *maximum = hi;
}

static inline void fill_row(float *p, size_t n, float a) {
    float32x4_t v = vdupq_n_f32(a);
    size_t j = 0;
    for (; n-j >= 4; j += 4) vst1q_f32(p+j, v);
    for (; j < n; ++j) p[j] = a;
}

static inline void scale_row(float *p, size_t n, float a) {
    float32x4_t v = vdupq_n_f32(a);
    size_t j = 0;
    for (; n-j >= 4; j += 4)
        vst1q_f32(p+j, vmulq_f32(vld1q_f32(p+j), v));
    for (; j < n; ++j) p[j] *= a;
}

static inline float cached_exp(float a, float *last_argument,
                               float *last_result) {
    if (a == *last_argument) return *last_result;
    float e = expf(a);
    *last_argument = a;
    *last_result = e;
    return e;
}

static inline void process_known_row(const float *p, float *o,
                                     size_t n, size_t s, float lo, float hi) {
    if (lo == hi) {
        fill_row(o, n, (float)(1.0/(double)n));
        return;
    }
    float last_argument = INFINITY, last_result = 0.0f;
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n-j >= 4; j += 4) {
        float e0 = cached_exp(p[j*s]-hi, &last_argument, &last_result);
        o[j] = e0;
        s0 += (double)e0;
        float e1 = cached_exp(p[(j+1)*s]-hi, &last_argument, &last_result);
        o[j+1] = e1;
        s1 += (double)e1;
        float e2 = cached_exp(p[(j+2)*s]-hi, &last_argument, &last_result);
        o[j+2] = e2;
        s2 += (double)e2;
        float e3 = cached_exp(p[(j+3)*s]-hi, &last_argument, &last_result);
        o[j+3] = e3;
        s3 += (double)e3;
    }
    for (; j < n; ++j) {
        float e = cached_exp(p[j*s]-hi, &last_argument, &last_result);
        o[j] = e;
        s0 += (double)e;
    }
    scale_row(o, n, (float)(1.0/((s0+s1)+(s2+s3))));
}

static inline void pack_four(const float *p, float *packed,
                             size_t n, size_t rs, size_t cs,
                             float *lo, float *hi) {
    float *p0 = packed;
    float *p1 = packed+n;
    float *p2 = packed+2*n;
    float *p3 = packed+3*n;
    float32x4_t h0 = vdupq_n_f32(-INFINITY), h1 = h0;
    float32x4_t l0 = vdupq_n_f32(INFINITY), l1 = l0;
    size_t j = 0;
    for (; n-j >= 4; j += 4) {
        float32x4_t a = read4(p+j*cs, rs);
        float32x4_t b = read4(p+(j+1)*cs, rs);
        float32x4_t c = read4(p+(j+2)*cs, rs);
        float32x4_t d = read4(p+(j+3)*cs, rs);
        h0 = vmaxq_f32(h0, a);
        h1 = vmaxq_f32(h1, b);
        h0 = vmaxq_f32(h0, c);
        h1 = vmaxq_f32(h1, d);
        l0 = vminq_f32(l0, a);
        l1 = vminq_f32(l1, b);
        l0 = vminq_f32(l0, c);
        l1 = vminq_f32(l1, d);
        float32x4x2_t ab = vtrnq_f32(a, b);
        float32x4x2_t cd = vtrnq_f32(c, d);
        float32x4_t t0 = vcombine_f32(vget_low_f32(ab.val[0]),
                                     vget_low_f32(cd.val[0]));
        float32x4_t t1 = vcombine_f32(vget_low_f32(ab.val[1]),
                                     vget_low_f32(cd.val[1]));
        float32x4_t t2 = vcombine_f32(vget_high_f32(ab.val[0]),
                                     vget_high_f32(cd.val[0]));
        float32x4_t t3 = vcombine_f32(vget_high_f32(ab.val[1]),
                                     vget_high_f32(cd.val[1]));
        vst1q_f32(p0+j, t0);
        vst1q_f32(p1+j, t1);
        vst1q_f32(p2+j, t2);
        vst1q_f32(p3+j, t3);
    }
    h0 = vmaxq_f32(h0, h1);
    l0 = vminq_f32(l0, l1);
    for (; j < n; ++j) {
        float32x4_t a = read4(p+j*cs, rs);
        h0 = vmaxq_f32(h0, a);
        l0 = vminq_f32(l0, a);
        p0[j] = vgetq_lane_f32(a, 0);
        p1[j] = vgetq_lane_f32(a, 1);
        p2[j] = vgetq_lane_f32(a, 2);
        p3[j] = vgetq_lane_f32(a, 3);
    }
    vst1q_f32(lo, l0);
    vst1q_f32(hi, h0);
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)inv; (void)pr;
    if (rows == 0 || cols == 0) return;
    if (cols == 1) {
        fill_row(out, rows, 1.0f);
        return;
    }
    size_t i = 0;
    if (rs < cs) {
        for (; rows-i >= 4; i += 4) {
            float lo[4], hi[4];
            pack_four(x+i*rs, px, cols, rs, cs, lo, hi);
            for (size_t q = 0; q < 4; ++q)
                process_known_row(px+q*cols, out+(i+q)*cols,
                                  cols, 1, lo[q], hi[q]);
        }
    }
    for (; i < rows; ++i) {
        float lo, hi;
        extrema(x+i*rs, cols, cs, &lo, &hi);
        process_known_row(x+i*rs, out+i*cols, cols, cs, lo, hi);
    }
}

#include <stddef.h>
#include <math.h>
#include <arm_neon.h>

static inline float32x4_t load_four(const float *p, size_t s) {
    if (s == 1) return vld1q_f32(p);
    float32x4_t v = vdupq_n_f32(p[0]);
    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2 * s], v, 2);
    return vsetq_lane_f32(p[3 * s], v, 3);
}

static inline void fill_row(float *y, size_t n, float value) {
    float32x4_t v = vdupq_n_f32(value);
    size_t j = 0;
    for (; n - j >= 8; j += 8) {
        vst1q_f32(y + j, v);
        vst1q_f32(y + j + 4, v);
    }
    for (; n - j >= 4; j += 4) vst1q_f32(y + j, v);
    for (; j < n; ++j) y[j] = value;
}

static inline void evaluate_row(const float *a, float *y, size_t n,
                                size_t s, float maximum, float *inverse) {
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n - j >= 4; j += 4) {
        float e0 = expf(a[j * s] - maximum);
        y[j] = e0;
        s0 += (double)e0;
        float e1 = expf(a[(j + 1) * s] - maximum);
        y[j + 1] = e1;
        s1 += (double)e1;
        float e2 = expf(a[(j + 2) * s] - maximum);
        y[j + 2] = e2;
        s2 += (double)e2;
        float e3 = expf(a[(j + 3) * s] - maximum);
        y[j + 3] = e3;
        s3 += (double)e3;
    }
    for (; j < n; ++j) {
        float e = expf(a[j * s] - maximum);
        y[j] = e;
        s0 += (double)e;
    }
    float scale = (float)(1.0 / ((s0 + s1) + (s2 + s3)));
    *inverse = scale;
    float32x4_t vscale = vdupq_n_f32(scale);
    j = 0;
    for (; n - j >= 8; j += 8) {
        float32x4_t v0 = vld1q_f32(y + j);
        float32x4_t v1 = vld1q_f32(y + j + 4);
        vst1q_f32(y + j, vmulq_f32(v0, vscale));
        vst1q_f32(y + j + 4, vmulq_f32(v1, vscale));
    }
    for (; n - j >= 4; j += 4)
        vst1q_f32(y + j, vmulq_f32(vld1q_f32(y + j), vscale));
    for (; j < n; ++j) y[j] *= scale;
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)px; (void)pr;
    if (rows == 0 || cols == 0) return;
    for (size_t row = 0; row < rows; ++row) {
        const float *a = x + row * rs;
        float *y = out + row * cols;
        float32x4_t mx0 = vdupq_n_f32(-INFINITY);
        float32x4_t mx1 = mx0;
        float32x4_t mn0 = vdupq_n_f32(INFINITY);
        float32x4_t mn1 = mn0;
        size_t j = 0;
        for (; cols - j >= 8; j += 8) {
            float32x4_t v0 = load_four(a + j * cs, cs);
            float32x4_t v1 = load_four(a + (j + 4) * cs, cs);
            mx0 = vmaxq_f32(mx0, v0);
            mx1 = vmaxq_f32(mx1, v1);
            mn0 = vminq_f32(mn0, v0);
            mn1 = vminq_f32(mn1, v1);
        }
        if (cols - j >= 4) {
            float32x4_t v = load_four(a + j * cs, cs);
            mx0 = vmaxq_f32(mx0, v);
            mn0 = vminq_f32(mn0, v);
            j += 4;
        }
        float maximum = vmaxvq_f32(vmaxq_f32(mx0, mx1));
        float minimum = vminvq_f32(vminq_f32(mn0, mn1));
        for (; j < cols; ++j) {
            float v = a[j * cs];
            if (v > maximum) maximum = v;
            if (v < minimum) minimum = v;
        }
        if (maximum == minimum) {
            float scale = (float)(1.0 / (double)cols);
            inv[row] = scale;
            fill_row(y, cols, scale);
        } else if (cs == 1) {
            evaluate_row(a, y, cols, 1, maximum, inv + row);
        } else {
            evaluate_row(a, y, cols, cs, maximum, inv + row);
        }
    }
}

#include <stddef.h>
#include <math.h>
#include <arm_neon.h>

static inline float32x4_t load_four(const float *p, size_t s) {
    if (s == 1) return vld1q_f32(p);
    float32x4_t v = vdupq_n_f32(p[0]);
    v = vsetq_lane_f32(p[s], v, 1);
    v = vsetq_lane_f32(p[2 * s], v, 2);
    return vsetq_lane_f32(p[3 * s], v, 3);
}

static inline void finish_row(const float *a, float *y, size_t n,
                              float maximum, float minimum, float *inverse) {
    if (maximum == minimum) {
        float scale = (float)(1.0 / (double)n);
        *inverse = scale;
        float32x4_t v = vdupq_n_f32(scale);
        size_t j = 0;
        for (; n - j >= 4; j += 4) vst1q_f32(y + j, v);
        for (; j < n; ++j) y[j] = scale;
        return;
    }
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n - j >= 4; j += 4) {
        float e0 = expf(a[j] - maximum);
        y[j] = e0;
        s0 += (double)e0;
        float e1 = expf(a[j + 1] - maximum);
        y[j + 1] = e1;
        s1 += (double)e1;
        float e2 = expf(a[j + 2] - maximum);
        y[j + 2] = e2;
        s2 += (double)e2;
        float e3 = expf(a[j + 3] - maximum);
        y[j + 3] = e3;
        s3 += (double)e3;
    }
    for (; j < n; ++j) {
        float e = expf(a[j] - maximum);
        y[j] = e;
        s0 += (double)e;
    }
    float scale = (float)(1.0 / ((s0 + s1) + (s2 + s3)));
    *inverse = scale;
    float32x4_t vscale = vdupq_n_f32(scale);
    j = 0;
    for (; n - j >= 8; j += 8) {
        float32x4_t v0 = vld1q_f32(y + j);
        float32x4_t v1 = vld1q_f32(y + j + 4);
        vst1q_f32(y + j, vmulq_f32(v0, vscale));
        vst1q_f32(y + j + 4, vmulq_f32(v1, vscale));
    }
    for (; n - j >= 4; j += 4)
        vst1q_f32(y + j, vmulq_f32(vld1q_f32(y + j), vscale));
    for (; j < n; ++j) y[j] *= scale;
}

static inline void prepare_row(const float *a, float *packed, size_t n,
                               size_t s, float *maximum, float *minimum) {
    float32x4_t mx = vdupq_n_f32(-INFINITY);
    float32x4_t mn = vdupq_n_f32(INFINITY);
    size_t j = 0;
    if (s == 1) {
        for (; n - j >= 4; j += 4) {
            float32x4_t v = vld1q_f32(a + j);
            mx = vmaxq_f32(mx, v);
            mn = vminq_f32(mn, v);
        }
    } else {
        for (; n - j >= 4; j += 4) {
            float32x4_t v = load_four(a + j * s, s);
            vst1q_f32(packed + j, v);
            mx = vmaxq_f32(mx, v);
            mn = vminq_f32(mn, v);
        }
    }
    float high = vmaxvq_f32(mx);
    float low = vminvq_f32(mn);
    for (; j < n; ++j) {
        float v = a[j * s];
        if (s != 1) packed[j] = v;
        if (v > high) high = v;
        if (v < low) low = v;
    }
    *maximum = high;
    *minimum = low;
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)pr;
    if (rows == 0 || cols == 0) return;
    size_t row = 0;
    if (rs == 1 && cs != 1) {
        for (; rows - row >= 4; row += 4) {
            float *p0 = px + row * cols;
            float *p1 = p0 + cols;
            float *p2 = p1 + cols;
            float *p3 = p2 + cols;
            float32x4_t mx0 = vdupq_n_f32(-INFINITY);
            float32x4_t mx1 = mx0;
            float32x4_t mn0 = vdupq_n_f32(INFINITY);
            float32x4_t mn1 = mn0;
            size_t j = 0;
            for (; cols - j >= 4; j += 4) {
                float32x4_t c0 = vld1q_f32(x + row + j * cs);
                float32x4_t c1 = vld1q_f32(x + row + (j + 1) * cs);
                float32x4_t c2 = vld1q_f32(x + row + (j + 2) * cs);
                float32x4_t c3 = vld1q_f32(x + row + (j + 3) * cs);
                mx0 = vmaxq_f32(mx0, vmaxq_f32(c0, c1));
                mx1 = vmaxq_f32(mx1, vmaxq_f32(c2, c3));
                mn0 = vminq_f32(mn0, vminq_f32(c0, c1));
                mn1 = vminq_f32(mn1, vminq_f32(c2, c3));
                float32x4x2_t t01 = vtrnq_f32(c0, c1);
                float32x4x2_t t23 = vtrnq_f32(c2, c3);
                vst1q_f32(p0 + j, vcombine_f32(vget_low_f32(t01.val[0]),
                                              vget_low_f32(t23.val[0])));
                vst1q_f32(p1 + j, vcombine_f32(vget_low_f32(t01.val[1]),
                                              vget_low_f32(t23.val[1])));
                vst1q_f32(p2 + j, vcombine_f32(vget_high_f32(t01.val[0]),
                                              vget_high_f32(t23.val[0])));
                vst1q_f32(p3 + j, vcombine_f32(vget_high_f32(t01.val[1]),
                                              vget_high_f32(t23.val[1])));
            }
            float32x4_t mx = vmaxq_f32(mx0, mx1);
            float32x4_t mn = vminq_f32(mn0, mn1);
            for (; j < cols; ++j) {
                float32x4_t v = vld1q_f32(x + row + j * cs);
                mx = vmaxq_f32(mx, v);
                mn = vminq_f32(mn, v);
                p0[j] = vgetq_lane_f32(v, 0);
                p1[j] = vgetq_lane_f32(v, 1);
                p2[j] = vgetq_lane_f32(v, 2);
                p3[j] = vgetq_lane_f32(v, 3);
            }
            float highs[4], lows[4];
            vst1q_f32(highs, mx);
            vst1q_f32(lows, mn);
            finish_row(p0, out + row * cols, cols,
                       highs[0], lows[0], inv + row);
            finish_row(p1, out + (row + 1) * cols, cols,
                       highs[1], lows[1], inv + row + 1);
            finish_row(p2, out + (row + 2) * cols, cols,
                       highs[2], lows[2], inv + row + 2);
            finish_row(p3, out + (row + 3) * cols, cols,
                       highs[3], lows[3], inv + row + 3);
        }
    }
    for (; row < rows; ++row) {
        const float *a = x + row * rs;
        float *packed = px + row * cols;
        float maximum, minimum;
        prepare_row(a, packed, cols, cs, &maximum, &minimum);
        const float *work = cs == 1 ? a : packed;
        finish_row(work, out + row * cols, cols,
                   maximum, minimum, inv + row);
    }
}

