}

static inline void fill_row(float *y, size_t n, float value) {
    float32x4_t v = vdupq_n_f32(value);
    size_t j = 0;
    for (; n - j >= 8; j += 8) {
        vst1q_f32(y + j, v);
        vst1q_f32(y + j + 4, v);
    }
    for (; n - j >= 4; j += 4) vst1q_f32(y + j, v);
