}

static inline float maximum_suffix(const float *a, size_t n, size_t s,
                                   size_t first, float seed) {
    float32x4_t mx0 = vdupq_n_f32(seed);
    float32x4_t mx1 = mx0;
    size_t j = first;
    for (; n - j >= 8; j += 8) {
        mx0 = vmaxq_f32(mx0, load_four(a + j * s, s));
        mx1 = vmaxq_f32(mx1, load_four(a + (j + 4) * s, s));
    }
    if (n - j >= 4) {
        mx0 = vmaxq_f32(mx0, load_four(a + j * s, s));
        j += 4;
    }
    float maximum = vmaxvq_f32(vmaxq_f32(mx0, mx1));
    for (; j < n; ++j) {
        float v = a[j * s];
        if (v > maximum) maximum = v;
    }
    return maximum;
}

static inline void evaluate_row(const float *a, float *y, size_t n,
                                size_t s, float maximum, float *inverse) {
    double s0 = 0.0, s1 = 0.0, s2 = 0.0, s3 = 0.0;
    size_t j = 0;
    for (; n - j >= 4; j += 4) {
        float e0 = expf(a[j * s] - maximum);
        y[j] = e0;
        s0 += (double)e0;
        float e1 = expf(a[(j + 1) * s] - maximum);
        y[j + 1] = e1;
        s1 += (double)e1;
        float e2 = expf(a[(j + 2) * s] - maximum);
        y[j + 2] = e2;
        s2 += (double)e2;
        float e3 = expf(a[(j + 3) * s] - maximum);
        y[j + 3] = e3;
        s3 += (double)e3;
    }
    for (; j < n; ++j) {
        float e = expf(a[j * s] - maximum);
        y[j] = e;
        s0 += (double)e;
    }
    float scale = (float)(1.0 / ((s0 + s1) + (s2 + s3)));
    *inverse = scale;
    float32x4_t vscale = vdupq_n_f32(scale);
    j = 0;
    for (; n - j >= 8; j += 8) {
        float32x4_t v0 = vld1q_f32(y + j);
        float32x4_t v1 = vld1q_f32(y + j + 4);
        vst1q_f32(y + j, vmulq_f32(v0, vscale));
        vst1q_f32(y + j + 4, vmulq_f32(v1, vscale));
    }
    for (; n - j >= 4; j += 4)
        vst1q_f32(y + j, vmulq_f32(vld1q_f32(y + j), vscale));
    for (; j < n; ++j) y[j] *= scale;
}

void kernel(const float *restrict x, const float *restrict r,
            const float *restrict w, float *restrict out,
            float *restrict inv, float *restrict px, float *restrict pr,
            size_t rows, size_t cols, size_t rs, size_t cs) {
    (void)r; (void)w; (void)px; (void)pr;
    if (rows == 0 || cols == 0) return;
    for (size_t row = 0; row < rows; ++row) {
        const float *a = x + row * rs;
        float *y = out + row * cols;
        float value_a = a[0];
        float32x4_t va = vdupq_n_f32(value_a);
        size_t j = 1;
        while (cols - j >= 4) {
            float32x4_t v = load_four(a + j * cs, cs);
            if (vminvq_u32(vceqq_f32(v, va)) == 0) break;
            j += 4;
        }
        while (j < cols && a[j * cs] == value_a) ++j;
        if (j == cols) {
            float scale = (float)(1.0 / (double)cols);
            inv[row] = scale;
            fill_row(y, cols, scale);
            continue;
        }
        float value_b = a[j * cs];
        float32x4_t vb = vdupq_n_f32(value_b);
        size_t count_a = j;
        size_t count_b = 1;
        ++j;
        while (cols - j >= 4) {
            float32x4_t v = load_four(a + j * cs, cs);
            uint32x4_t matches_a = vceqq_f32(v, va);
            uint32x4_t matches_b = vceqq_f32(v, vb);
            if (vminvq_u32(vorrq_u32(matches_a, matches_b)) == 0) break;
            size_t number_a = (size_t)vaddvq_u32(vshrq_n_u32(matches_a, 31));
            count_a += number_a;
            count_b += 4 - number_a;
            j += 4;
        }
        for (; j < cols; ++j) {
            float v = a[j * cs];
            if (v == value_a) ++count_a;
            else if (v == value_b) ++count_b;
            else break;
        }
        float maximum = value_a > value_b ? value_a : value_b;
        if (j == cols) {
            float ea = value_a == maximum ? 1.0f : expf(value_a - maximum);
            float eb = value_b == maximum ? 1.0f : expf(value_b - maximum);
            double sum = (double)count_a * (double)ea
                       + (double)count_b * (double)eb;
            float scale = (float)(1.0 / sum);
            inv[row] = scale;
            float probability_a = ea * scale;
            float probability_b = eb * scale;
            float32x4_t pa = vdupq_n_f32(probability_a);
            float32x4_t pb = vdupq_n_f32(probability_b);
            j = 0;
            for (; cols - j >= 4; j += 4) {
                float32x4_t v = load_four(a + j * cs, cs);
                uint32x4_t mask = vceqq_f32(v, va);
                vst1q_f32(y + j, vbslq_f32(mask, pa, pb));
            }
            for (; j < cols; ++j)
                y[j] = a[j * cs] == value_a ? probability_a : probability_b;
        } else {
            maximum = maximum_suffix(a, cols, cs, j, maximum);
            if (cs == 1)
                evaluate_row(a, y, cols, 1, maximum, inv + row);
            else
                evaluate_row(a, y, cols, cs, maximum, inv + row);
        }
    }
}
